ADB=/nix/store/qalfgcmwsd2mmj652qk6ysajv20h2yzg-android-tools-35.0.2/bin/adb
$ADB shell 'ls -d /proc/clkdbg* /proc/clkmgr* /sys/kernel/debug/clkdbg* /proc/mtk_* 2>/dev/null; for d in /proc/clkdbg /sys/kernel/debug/clkdbg; do [ -d $d ] && { echo "### $d"; ls $d; for f in $d/*; do echo "--- $f"; head -c 20000 $f 2>&1 | head -300; done; }; done; echo "### clk rates"; for c in axi_sel mem_sel ddrphycfg_sel mm_sel pmicspi_sel aud_intbus_sel audio_sel; do echo "$c $(cat /sys/kernel/debug/clk/$c/clk_rate 2>/dev/null) parent=$(cat /sys/kernel/debug/clk/$c/clk_parent 2>/dev/null)"; done' > /root/douglas-flash/vendor_clkdbg.txt 2>&1; wc -l /root/douglas-flash/vendor_clkdbg.txt; head -60 /root/douglas-flash/vendor_clkdbg.txt
